contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(c).balance >= amount);
        if (receiver == address(this)) {
            require(address(this).balance >= amount);
        }
        uint recipientBefore = receiver.balance;
        uint contractBefore = address(c).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint recipientAfter = receiver.balance;
        uint contractAfter = address(c).balance;

        assert(
            (reverted && recipientAfter == recipientBefore && contractAfter == contractBefore) ||
            (!reverted && recipientAfter == recipientBefore + amount && contractAfter == contractBefore - amount)
        );
    }

    receive() external payable {}
}

