pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(c).balance >= amount);
        if (receiver == address(this)) {
            require(address(this).balance >= amount);
        }
        uint recipientBefore = receiver.balance;
        uint contractBefore = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint recipientAfter = receiver.balance;
        uint contractAfter = address(c).balance;
        assertTrue((reverted && recipientAfter == recipientBefore && contractAfter == contractBefore) ||
            (!reverted && recipientAfter == recipientBefore + amount && contractAfter == contractBefore - amount));
    }

    function testFuzz_run(address receiver, uint256 amount) public {
        vm.assume(receiver.code.length == 0 && uint160(receiver) > 0xffff && receiver != address(this) && receiver != address(c) && receiver != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(receiver, amount);
    }

    receive() external payable {}
}
